import json

# Công cụ thật (hàm Python thường)
def get_price(item):
    prices = {"apple": 1.2, "pear": 2.0}
    if item not in prices:
        raise KeyError(f"không có {item}")
    return prices[item]

TOOLS = {"get_price": get_price}

# "Mô hình" giả lập: kịch bản hành động theo từng bước (thay bằng LLM thật ở sản xuất)
script = [
    {"tool": "get_price", "args": {"item": "apple"}},
    {"tool": "get_price", "args": {"item": "kiwi"}},          # lỗi: sẽ được phản hồi lại
    {"tool": "get_price", "args": {"item": "pear"}},
    {"final": "apple 1.2 và pear 2.0"},
]

def run_agent(script, max_steps=5):
    memory, cost = [], 0
    for step, action in enumerate(script):
        if step >= max_steps:
            return "dừng: quá số bước", memory
        if "final" in action:
            return action["final"], memory
        try:
            obs = TOOLS[action["tool"]](**action["args"])
        except Exception as e:                      # lỗi công cụ -> quan sát, để mô hình tự sửa
            obs = f"LỖI: {e}"
        memory.append((action["tool"], action["args"], obs))
    return "dừng: hết kịch bản", memory

answer, mem = run_agent(script)
print(answer)
print([m[2] for m in mem])
print(run_agent(script, max_steps=2)[0])

