def run_agent(script, max_steps):
    n = 0
    for a in script:
        if 'final' in a or n >= max_steps:
            break
        n += 1
    return n

script = [{'tool': 'a'}, {'tool': 'b'}, {'tool': 'c'}, {'final': 'ok'}]
print(run_agent(script, 10))
print(run_agent(script, 2))

def safe_call(fn, **kw):
    try:
        return fn(**kw)
    except Exception as e:
        return f'ERR: {e}'

fn = lambda k: {'a': 1}[k]
print(safe_call(fn, k='a'))
print(safe_call(fn, k='z')[:5])
